import { Component, EventEmitter, Input, Output, SimpleChanges, ViewChild } from '@angular/core';
import { CobroModalidad, CreditoEventoCobro } from '../../../models/credito.evento.cobro';
import { CreditoEventoCobroService } from '../../../controllers/credito.evento.cobro.service';

import { UtilsService } from '../../../services/utils.service';
import { ActivatedRoute, Router } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { FileInputComponent } from "../../../shared/file-input/file-input.component";
import { Credito } from '../../../models/credito.model';
import { EventoCobroModalidad, EventoCobroObjetivo } from '../../../models/evento.cobro.objetivo.model';
import { EventoCobroObjetivoService } from '../../../controllers/evento.cobro.objetivo.service';
import { LocalStorageService } from '../../../services/localStorage/local-storage.service';
import { CreditoService } from '../../../controllers/credito.service';
import { Conditional, SuperServiceConditional, SuperServiceOptions } from '../../../controllers/super.service';
import { EventoCobroAsignacion } from '../../../models/evento.cobro.asignacion';
import { EventoCobroAsignacionService } from '../../../controllers/evento.cobro.asignacion.service';

const FORMS_DEF: { titulo: string; modalidad: CobroModalidad; objetivo: string; detalle: string; }[] = [
  {
    titulo: 'Nuevo Número Telefónico:',
    modalidad: 'LLAMADA',
    objetivo: 'Número',
    detalle: 'Tipo:',
  },
  {
    titulo: 'Nuevo Domicilio:',
    modalidad: 'NOTIFICACION DOMICILIARIA',
    objetivo: 'Domicilio',
    detalle: 'Tipo:',
  },
  {
    titulo: 'Nuevo Correo Electrónico:',
    modalidad: 'CORREO ELECTRONICO',
    objetivo: 'Correo',
    detalle: 'Tipo:',
  },
  {
    titulo: 'Nuevo Tipo de Contacto:',
    modalidad: 'OTRO',
    objetivo: 'Contacto',
    detalle: 'Tipo:',
  },
]

interface Objetivo {
  data: string;
  label: string;
  isSelected?: boolean;
}

@Component({
  selector: 'app-ejecucion-cobro',
  imports: [
    FormsModule,
    FileInputComponent
  ],
  templateUrl: './ejecucion-cobro.component.html',
  styleUrl: './ejecucion-cobro.component.css'
})
export class EjecucionCobroComponent {
  @ViewChild('fileInput') fileInput?: FileInputComponent
  @Input() evento?: CreditoEventoCobro
  @Input() credito?: Credito
  @Input() div: string = 'container-fluid my-1 p-3 pb-4 bg-white rounded shadow border'
  @Output() onSaved = new EventEmitter()
  addFile: 'NO' | 'SI' = 'NO'

  objetivos: Objetivo[] = []

  eventoObjetivoToCreate: EventoCobroObjetivo[] = []

  eventoCobroAsignaciones: EventoCobroAsignacion[]=[]
  asignacionCompletada?: EventoCobroAsignacion

  showForm = false
  objetivoForm: EventoCobroObjetivo = {
    objetivo: '',
    detalle: '',
    modalidad: 'OTRO',
    evento_cobro_id: 0,
    id: 0,
    deleted_at: null,
    created_at: '',
    updated_at: null
  }

  titleObjetivo: string = ''

  formularios = FORMS_DEF

  constructor(
    private creditoController: CreditoService,
    private cobroController: CreditoEventoCobroService,
    private cobroObjetivoController: EventoCobroObjetivoService,
    public utils: UtilsService,
    private route: ActivatedRoute,
    private storage: LocalStorageService,
    private eventoCobroAsignacionController: EventoCobroAsignacionService,
  ) { }

  ngOnInit() {
    this.subscribeToRouteParams();
  }

  ngOnChanges(changes: SimpleChanges) {
    if (changes['evento'] && this.evento) {
      this.setObjetivos()
      this.setAsignacionesPendientes()
    }
  }

  private async setAsignacionesPendientes(){
    this.eventoCobroAsignaciones= (await this.eventoCobroAsignacionController.asignacionesPendientes(this.credito)).filter(a => a.modalidad===this.evento?.modalidad)
  }

  selectObjetivo(objetivo: Objetivo) {
    if (!this.evento) return;
    if (objetivo.isSelected) {
      objetivo.isSelected = false
      return
    }
    this.objetivos.forEach(ob => ob.isSelected = false)
    objetivo.isSelected = true
    this.evento.objetivo = objetivo.data
    this.evento.objetivo_detalle = objetivo.label
  }

  public async setObjetivos() {
    if (!this.credito || !this.evento) return;
    this.setTituloObjetivo()
    switch (this.evento.modalidad) {
      case 'LLAMADA':
        await this.setTelefonosObjetivos()
        break;
      case 'NOTIFICACION DOMICILIARIA':
        await this.setDomiciliosObjetivos()
        break;
      case 'CORREO ELECTRONICO':
        await this.setCorreosObjetivos()
        break;
      case 'OTRO':
        await this.setOtrosObjetivos()
        break;
    }
    this.objetivos = this.objetivos.filter(ob => !!ob.data)
  }

  public nuevoObjetivo() {
    this.showForm = !this.showForm
    this.objetivoForm = {
      objetivo: '',
      detalle: '',
      modalidad: 'OTRO',
      evento_cobro_id: this.evento!.id,
      id: 0,
      deleted_at: null,
      created_at: '',
      updated_at: null
    }
  }

  public async saveObjetivo(modalidad: 'LLAMADA' | 'NOTIFICACION DOMICILIARIA' | 'CORREO ELECTRONICO' | 'OTRO') {
    this.objetivos.push({
      data: this.objetivoForm.objetivo,
      label: this.objetivoForm.detalle
    })
    this.objetivoForm.modalidad = modalidad
    this.eventoObjetivoToCreate.push(this.objetivoForm)
    this.showForm = false
  }


  private setTituloObjetivo() {
    switch (this.evento?.modalidad) {
      case 'LLAMADA':
        this.titleObjetivo = 'Números Telefónicos'
        break
      case 'CORREO ELECTRONICO':
        this.titleObjetivo = 'Correos electrónicos'
        break;
      case 'NOTIFICACION DOMICILIARIA':
        this.titleObjetivo = 'Domicilios'
        break;
      case 'OTRO':
        break;
    }
  }

  private async setTelefonosObjetivos() {
    if (!this.credito) return;
    this.objetivos = [
      ...(this.credito.datos_persona_fisica?.datos_personales?.telefonos_personales ?? []).map(tel => ({ data: tel.numero, label: 'ACREDITADO' })),
      ...(this.credito.datos_personas_morales?.telefonos ?? []).map(tel => ({ data: tel.numero, label: 'ACREDITADO' })),
      ...(this.credito.datos_personales?.telefonos_personales ?? []).map(tel => ({ data: tel.numero, label: 'AVAL' })),
      ...(this.credito.referencias_personales ?? []).map(ref => ({ data: ref.telefono, label: 'REFERENCIA' })),
      ...await this.objetivosByModalidad('LLAMADA')
    ]
  }

  private async setDomiciliosObjetivos() {
    if (!this.credito) return;

    this.objetivos = []
    if (this.credito.datos_persona_fisica?.datos_personales) {
      this.objetivos.push({
        data: this.utils.domicilioFromDatosModel(this.credito.datos_persona_fisica.datos_personales),
        label: 'ACREDITADO'
      })
    }
    if (this.credito.datos_persona_fisica?.datos_personales?.conyuge_direccion) {
      this.objetivos.push({
        data: this.credito.datos_persona_fisica.datos_personales.conyuge_direccion,
        label: 'CONYUGE'
      })
    }

    if (this.credito.datos_personas_morales) {
      this.objetivos.push({
        data: this.utils.domicilioFromDatosModel(this.credito.datos_personas_morales),
        label: 'ACREDITADO'
      })
    }
    if (this.credito.datos_personas_morales?.representante_legal) {
      this.objetivos.push({
        data: this.utils.domicilioFromDatosModel(this.credito.datos_personas_morales.representante_legal),
        label: 'ACREDITADO RL'
      })
    }
    if (this.credito.datos_personas_morales?.representante_legal?.conyuge_direccion) {
      this.objetivos.push({
        data: this.credito.datos_personas_morales.representante_legal.conyuge_direccion,
        label: 'CONYUGE RL'
      })
    }
    if (this.credito.datos_personales) {
      this.objetivos.push({
        data: this.utils.domicilioFromDatosModel(this.credito.datos_personales),
        label: 'AVAL'
      })
    }
    if (this.credito.datos_personales?.conyuge_direccion) {
      this.objetivos.push({
        data: this.credito.datos_personales.conyuge_direccion,
        label: 'AVAL'
      })
    }
    this.objetivos = [
      ...this.objetivos,
      ...(await this.objetivosByModalidad('NOTIFICACION DOMICILIARIA'))
    ]
  }

  private async setCorreosObjetivos() {
    if (!this.credito) return;

    this.objetivos = []
    if (this.credito.datos_persona_fisica?.datos_personales) {
      this.objetivos.push({
        data: this.credito.datos_persona_fisica.datos_personales.email,
        label: 'ACREDITADO'
      })
    }
    if (this.credito.datos_persona_fisica?.datos_personales?.conyuge_correo) {
      this.objetivos.push({
        data: this.credito.datos_persona_fisica.datos_personales.conyuge_correo,
        label: 'CONYUGE'
      })
    }
    if (this.credito.datos_personas_morales) {
      this.objetivos.push({
        data: this.credito.datos_personas_morales.email,
        label: 'ACREDITADO'
      })
    }
    if (this.credito.datos_personas_morales?.representante_legal) {
      this.objetivos.push({
        data: this.credito.datos_personas_morales.representante_legal.email,
        label: 'ACREDITADO RL'
      })
    }
    if (this.credito.datos_personas_morales?.representante_legal?.conyuge_correo) {
      this.objetivos.push({
        data: this.credito.datos_personas_morales.representante_legal.conyuge_correo,
        label: 'RL CONYUGE'
      })
    }
    if (this.credito.datos_personales) {
      this.objetivos.push({
        data: this.credito.datos_personales.email,
        label: 'AVAL'
      })
    }
    if (this.credito.datos_personales) {
      this.objetivos.push({
        data: this.credito.datos_personales.conyuge_correo,
        label: 'AVAL CÓNYUGUE'
      })
    }
    this.objetivos = [
      ...this.objetivos,
      ...await this.objetivosByModalidad('CORREO ELECTRONICO')
    ]
  }

  private async setOtrosObjetivos() {
    this.objetivos = await this.objetivosByModalidad('OTRO')
  }

  private async objetivosByModalidad(modalidad: EventoCobroModalidad|undefined):Promise<{data:string;label:string}[]> {
    return (await this.cobroObjetivoController.all(
      {
        conditionals: {
          modalidad: modalidad,
          deleted_at: null,
        },
        relations:['creditoEventosCobros'],
        advancedSearch: [
          {
            relation: 'creditoEventosCobros',
            conditionals: [],
            andConditionals: [
              ['credito_id', '=', this.credito?.id]
            ]
          }
        ],
        loader: false
      }
    )).map(obj => ({ data: obj.objetivo, label: obj.detalle }))
  }

  /**
   * Suscribe a los cambios en los parámetros de la ruta y carga el evento de cobro si existe.
   */
  private subscribeToRouteParams() {
    this.route.paramMap.subscribe(async (params) => {
      const eventId = this.getEventIdFromParams(params);
      if (eventId) {
        await this.loadEvento(eventId);
        await this.loadCredito();
        this.setObjetivos()
      }
    });
  }

  private async loadCredito() {
    if (this.evento) {
      this.credito = await this.creditoController.find(this.evento.credito_id, ['*'])
    }
  }

  /**
   * Obtiene el ID del evento de cobro de los parámetros de la ruta.
   * @param params - Mapa de parámetros de la ruta.
   * @returns El ID del evento de cobro o null si no es válido.
   */
  private getEventIdFromParams(params: any): number | null {
    return this.utils.intOrNull(params.get('credito_evento_cobro_id'));
  }

  /**
   * Carga el evento de cobro desde el servicio.
   * @param eventId - ID del evento de cobro a cargar.
   */
  private async loadEvento(eventId: number) {
    this.evento = await this.cobroController.find(eventId, ['*']);
    if (this.evento) {
      this.evento.fecha = this.evento.fecha?.substring(0, 10) ?? ''
    }
  }

  public isFormValid(){
    return !(!this.evento?.comentario || !this.evento?.fecha ||  (!this.evento?.objetivo && this.objetivos.length) || this.showForm || (!this.asignacionCompletada && this.eventoCobroAsignaciones.length))
  }

  /**
   * Método que se ejecuta al enviar el formulario.
   * Ejecuta el cobro del evento y emite un evento para notificar que se ha guardado.
   */
  public async submit() {
    if (!this.evento) return;
    if(!this.asignacionCompletada && this.eventoCobroAsignaciones.length) return;

    if (!this.evento.nombre_usuario) {
      this.evento.nombre_usuario = this.storage.getUser().nombre + ' ' + this.storage.getUser().apellido_paterno + ' ' + this.storage.getUser().apellido_materno
    }

    const res = await this.cobroController.createOrUpdate(this.evento)
    if (res && this.eventoObjetivoToCreate.length > 0) {
      this.eventoObjetivoToCreate.forEach((obj) => obj.evento_cobro_id = res.id)
      await this.cobroObjetivoController.multipleNews(this.eventoObjetivoToCreate)
    }

    if (res) {
      if (this.fileInput && this.fileInput.file) {
        this.fileInput.formExtra = {
          id: res.id,
        }
        const fileRes = await this.fileInput.upload()
        if (!fileRes) return;
      }

      if(this.asignacionCompletada){
        await this.eventoCobroAsignacionController.marcarAsignacionCompletada(res, this.asignacionCompletada)
      }
    }
    this.evento.usuarios = this.storage.getUser();
    this.notifySave();
  }

  /**
   * Notifica que el evento ha sido guardado emitiendo un evento.
   */
  private notifySave() {
    this.onSaved.emit();
  }
}
