import { Injectable, Injector } from '@angular/core';
import { SuperService } from './super.service';
import { CreditoEventoCobro } from '../models/credito.evento.cobro';
import { firstValueFrom } from 'rxjs';

@Injectable({
  providedIn: 'any'
})
export class CreditoEventoCobroService extends SuperService<CreditoEventoCobro> {
  protected override model: string ="credito_eventos_cobros";
  protected override columns: (keyof CreditoEventoCobro)[] = [
    'id',
    'credito_id',
    'usuario_ejecutivo_id',
    'modalidad',
    'resultado',
    'comentario',
    'documento_url',
    'fecha',
    'usuario_id',
    'nombre_usuario',
    'objetivo',
    'otro_resultado',
  ];
  constructor(injector: Injector){
    super(injector)
  }

  public async ejecutarCobro(cobro:CreditoEventoCobro|undefined){
    if(!cobro) return;

    const res =await this.createOrUpdate(cobro)
    return !!res
  }
}