import { inject, Injectable, Injector } from '@angular/core';
import { SuperService } from './super.service';
import { EventoCobroAsignacion } from '../models/evento.cobro.asignacion';
import { LocalStorageService } from '../services/localStorage/local-storage.service';
import { Credito } from '../models/credito.model';
import { AdvancedSearchFilter } from '../shared/tabla/tabla.component';
import { CreditoEventoCobro } from '../models/credito.evento.cobro';
import { EventoCobroAsignacionUsuario } from '../models/evento.cobro.asignacion.usuario';
import { EventoCobroAsignacionUsuarioService } from './evento.cobro.asignacion.usuario.service';

@Injectable({
    providedIn: 'any'
})
export class EventoCobroAsignacionService extends SuperService<EventoCobroAsignacion> {
    protected override model: string = "evento_cobro_asignaciones";
    protected override columns: (keyof EventoCobroAsignacion)[] = [
        'fecha',
        'modalidad',
        'credito_id',
        'comentarios',
        'usuario_id',
        'created_at',
        'updated_at',
        'deleted_at',
    ];

    private eventoCobroAsignacionUsuarioController = inject(EventoCobroAsignacionUsuarioService)
    private localStorage = inject(LocalStorageService);

    constructor(injector: Injector) {
        super(injector)
    }

    public async asignacionesPendientes(credito: Credito | number | undefined): Promise<EventoCobroAsignacion[]> {
        let credito_id=0;
        if (!credito) return [];
        if(typeof credito == 'number'){
            credito_id= credito
        }else{
            credito_id= credito.id
        }

        const usuario = this.localStorage.getUser()
        return this.all({
            conditionals: {
                credito_id: credito_id,
                estado: 'EN PROGRESO',
                deleted_at: null,
            },
            advancedSearch: [
                {
                    relation: 'eventoCobroAsignacionUsuarios',
                    conditionals: [],
                    andConditionals: [
                        ['usuario_asignado_id', '=', usuario.id]
                    ],
                }
            ],
            relations:['eventoCobroAsignacionUsuarios', 'usuarios'],
            loader: false,
        })
    }

    public async marcarAsignacionCompletada(eventoCobro:CreditoEventoCobro|undefined, asignacion:EventoCobroAsignacion){
        if(!eventoCobro?.id) return;
        const usuario = this.localStorage.getUser()
        const asignacionesUsuario:EventoCobroAsignacionUsuario[] = asignacion.evento_cobro_asignacion_usuarios!.filter(a => a?.usuario_asignado_id=== usuario.id )
        asignacion.estado='COMPLETADA'

        await this.update(asignacion)
        await this.eventoCobroAsignacionUsuarioController.multipleUpdate(asignacionesUsuario.map(a => ({ id:a.id, credito_eventos_cobro_id:eventoCobro.id })))
    }
}